class ConcurrencyConflictError extends Error {}
class InMemoryOrderRepository {
  constructor() {
    this.store = new Map();
  }
  save(order) {
    const existing = this.store.get(order.id);
    if (existing && existing.version !== order.version) {
      throw new ConcurrencyConflictError(order.id);
    }
    const nextVersion = (existing ? existing.version : 0) + 1;
    this.store.set(order.id, { ...order, version: nextVersion });
  }
  findById(id) {
    return this.store.get(id);
  }
}

